import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const u=JSON.parse('{"title":"Visualizers","description":"","frontmatter":{},"headers":[],"relativePath":"VISUALIZERS.md","filePath":"VISUALIZERS.md"}'),s={name:"VISUALIZERS.md"};function n(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="visualizers" tabindex="-1">Visualizers <a class="header-anchor" href="#visualizers" aria-label="Permalink to &quot;Visualizers&quot;">​</a></h1><p>While a song plays in real time, Arrange can show a visualizer in place of its clips: a moving picture in full colour, drawn in the terminal from the notes being played. The track names and scene names stay where they are, so the song&#39;s shape stays visible around the picture. This page covers showing a visualizer, every mode, and recording a visualizer.</p><p><a href="https://www.youtube.com/watch?v=yt9NffJ1HF4" target="_blank" rel="noreferrer">A video of the visualizers playing a song</a> is on YouTube.</p><h2 id="visualizer-controls" tabindex="-1">Visualizer Controls <a class="header-anchor" href="#visualizer-controls" aria-label="Permalink to &quot;Visualizer Controls&quot;">​</a></h2><p>Visualizers need real-time playback, so the set&#39;s Real Time switch has to be on; <code>T</code> on the main screen turns it on, and every example has it on. On Arrange, these keys control the visualizer:</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Z</code></td><td>Show the first visualizer mode over the clip area, and each press after that the next mode, and after the last, the clips again.</td></tr><tr><td><code>Esc</code></td><td>Bring the clips back, staying on Arrange.</td></tr></tbody></table><p>A visualizer can show while nothing plays, and follows the music once the song starts with <code>Space</code> on the corner. When the mode changes, the mode&#39;s name shows near the bottom for eight seconds, steady, and then goes away.</p><p>A visualizer hears the notes as they are played, with their tracks, pitches and velocities, and the song&#39;s beat. It never hears the sound itself, so a visualizer works the same through FluidSynth, a hardware synthesizer or a DAW, and never knows a note before the note plays.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>What it shows</th></tr></thead><tbody><tr><td>Lava lamp</td><td>A blob of colour for each track, drifting on a path of its own; every note splashes a ripple into it, held notes keep pushing, and the whole picture turns and breathes with the beat. Dark in silence.</td></tr><tr><td>Spectrum</td><td>A bar for each band of pitches, low at the left, lifted by each note&#39;s velocity, its neighbours a little, falling back steadily, with caps that hang and drop, green to yellow to red.</td></tr><tr><td>MilkDrop</td><td>A feedback picture in the spirit of the classic: each frame the last one warped, zoomed, turned and swirled, with notes splashed in on a slowly turning circle.</td></tr><tr><td>Llamas</td><td>An ASCII llama for each track that plays, strolling, turning at the edges, bobbing with the beat and hopping on its notes, growing and glowing as its track gets busier.</td></tr><tr><td>Hypercube</td><td>A tesseract turning in four dimensions, faster with the tempo, its edges shared out among the tracks&#39; colours and glowing, pulsing with the beat. Bright even in silence.</td></tr><tr><td>Fireworks</td><td>A rocket for each note, bursting into sparks that fall and fade.</td></tr><tr><td>WarpZone</td><td>A ball for each track bouncing at the song&#39;s tempo, sending out slow rings.</td></tr><tr><td>Pipes</td><td>The old screensaver&#39;s pipes, one for each track, laid as its notes play.</td></tr><tr><td>Plasma</td><td>Waves of colour blended from the playing tracks&#39; colours.</td></tr><tr><td>Maze</td><td>A maze carved on screen, with a walker for each track.</td></tr><tr><td>Mystify</td><td>The old screensaver&#39;s polygons with trails, over a field of stars, their corners following the held notes.</td></tr><tr><td>Laser Llama</td><td>A neon sunset over a perspective grid, and a llama firing beams on the notes.</td></tr><tr><td>Mandelbrot</td><td>The Mandelbrot set turning about a point on its edge, breathing in and out, coloured from the tracks&#39; hues.</td></tr><tr><td>Life</td><td>Conway&#39;s Game of Life over a drifting gradient of the tracks&#39; colours, stepping on the beat, with notes seeding new cells.</td></tr><tr><td>Digital rain</td><td>Green streams of ones and zeros falling down the screen, a stream for each note in the column of its pitch, as bright as the note is loud, the green brightening as more plays.</td></tr><tr><td>Cycle</td><td>Each mode above in turn, a new one every fifteen seconds.</td></tr></tbody></table><p>Every track has a colour of its own, which each mode leans by pitch and brightens by octave, so a track looks the same across modes.</p><h2 id="eye-safety" tabindex="-1">Eye Safety <a class="header-anchor" href="#eye-safety" aria-label="Permalink to &quot;Eye Safety&quot;">​</a></h2><p>No mode strobes or flashes, since some people are sensitive to flashing light. Brightness rises and falls gently, a limiter holds the whole picture down as more plays, and nothing jumps to white.</p><h2 id="terminal-support" tabindex="-1">Terminal Support <a class="header-anchor" href="#terminal-support" aria-label="Permalink to &quot;Terminal Support&quot;">​</a></h2><p>A visualizer draws in full colour where the terminal supports it, and in the nearest of 256 or 16 colours otherwise. A bigger window shows more detail, and every mode fits the window&#39;s size, starting again when the window is resized.</p><h2 id="launching-and-recording" tabindex="-1">Launching and Recording <a class="header-anchor" href="#launching-and-recording" aria-label="Permalink to &quot;Launching and Recording&quot;">​</a></h2><p>A set can open straight onto a visualizer, playing, from the command line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>llamatron examples/by_genre/electronic/edm_density.yml --visualizer lava_lamp</span></span></code></pre></div><p>The mode names on the command line are <code>lava_lamp</code>, <code>spectrum</code>, <code>milkdrop</code>, <code>llamas</code>, <code>hypercube</code>, <code>fireworks</code>, <code>warpzone</code>, <code>pipes</code>, <code>plasma</code>, <code>maze</code>, <code>mystify</code>, <code>laser_llama</code>, <code>mandelbrot</code>, <code>life</code>, <code>digital_rain</code> and <code>cycle</code>.</p><p>Every visualizer can be recorded into a video with its sound, as <a href="./RECORDING">Recording</a> describes.</p>',20)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
